import{_ as p,a0 as u,w as d,s as i,ao as l,I as r,x as t,a1 as n,A as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const f=JSON.parse('{"title":"如何在Ubuntu 14.04上安装轻量级web服务器Cherokee | LCTT x X-CMD","titleTemplate":false,"description":"如何在Ubuntu 14.04上安装轻量级web服务器Cherokee | LCTT (201504) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在Ubuntu 14.04上安装轻量级web服务器Cherokee | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在Ubuntu 14.04上安装轻量级web服务器Cherokee | LCTT (201504) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201504/20150119 How to Install Cherokee Lightweight Web Server on Ubuntu 14.04","title":"如何在Ubuntu 14.04上安装轻量级web服务器Cherokee","tag":"201504","desc":""},"relativePath":"201504/20150119 How to Install Cherokee Lightweight Web Server on Ubuntu 14.04.md","filePath":"[post].md"}'),s={name:"201504/20150119 How to Install Cherokee Lightweight Web Server on Ubuntu 14.04.md"};function h(b,e,k,m,C,g){const o=u("Link");return d(),i("div",null,[e[17]||(e[17]=l(`<h1 id="如何在ubuntu-14-04上安装轻量级web服务器cherokee" tabindex="-1">如何在Ubuntu 14.04上安装轻量级web服务器Cherokee <a class="header-anchor" href="#如何在ubuntu-14-04上安装轻量级web服务器cherokee" aria-label="Permalink to “如何在Ubuntu 14.04上安装轻量级web服务器Cherokee”">​</a></h1><p><strong>Cherokee</strong> 是一个免费，开源，高性能轻量级的全功能web服务器，支持大部分主流操作系统(Linux、 Mac OS X、 Solaris 和 BSD)。它支持TLS/SSL、FastCGI、 SCGI、 PHP、 uWSGI、 SSI、 CGI、 LDAP、 HTTP代理、 视频流处理、 内容缓存、 流量控制、 虚拟主机、Apache兼容的日志文件，以及负载均衡等功能。</p><p>今天我们介绍一下怎样在Ubuntu Server 14.04 LTS安装和配置轻量级的web服务器Cherokee，只需要注意修改软件源列表，同样适用于Ubuntu12.04，12.10和13.04。</p><p>在Ubuntu Server上逐步安装和配置Cherokee</p><h3 id="_1-更新ubuntu软件包索引" tabindex="-1">1. 更新Ubuntu软件包索引 <a class="header-anchor" href="#_1-更新ubuntu软件包索引" aria-label="Permalink to “1. 更新Ubuntu软件包索引”">​</a></h3><p>首先登陆Ubuntu Server，执行以下命令，更新Ubuntu Server的软件源并安装可用的更新。</p><pre><code>sudo apt-get update

sudo apt-get upgrade
</code></pre><h3 id="_2-加入-ppa" tabindex="-1">2. 加入 PPA <a class="header-anchor" href="#_2-加入-ppa" aria-label="Permalink to “2. 加入 PPA”">​</a></h3><p>通过运行以下命令增加Cherokee的PPA</p><pre><code>sudo add-apt-repository ppa:cherokee-webserver

sudo apt-get update
</code></pre><p>对于运行14.04版本的服务器还需要执行以下步骤</p><pre><code>cd /etc/apt/sources.list.d

nano cherokee-webserver-ppa-trusty.list
</code></pre><p>用<code>deb http://ppa.launchpad.net/cherokee-webserver/ppa/ubuntu saucy main</code> 替换 <code>deb http://ppa.launchpad.net/cherokee-webserver/ppa/ubuntu trusty main</code></p><p><strong>再次运行命令:</strong></p><pre><code>sudo apt-get update
</code></pre><h3 id="_3-使用apt-get安装cherokee" tabindex="-1">3. 使用apt-get安装Cherokee <a class="header-anchor" href="#_3-使用apt-get安装cherokee" aria-label="Permalink to “3. 使用apt-get安装Cherokee”">​</a></h3><p>使用如下命令安装Cherokee和SSL模块</p><pre><code>sudo apt-get install cherokee cherokee-admin cherokee-doc libcherokee-mod-libssl libcherokee-mod-streaming libcherokee-mod-rrd
</code></pre><h3 id="_4-配置cherokee" tabindex="-1">4. 配置Cherokee <a class="header-anchor" href="#_4-配置cherokee" aria-label="Permalink to “4. 配置Cherokee”">​</a></h3><p>重启Cherokee服务：</p><pre><code>sudo service cherokee start
</code></pre><p>使用Cherokee最大的好处就是能通过一个简单易用的web界面 cherokee-admin 来管理所有的配置选项。推荐通过浏览器来管理Cherokee。使用如下命令启动cherokee-admin</p><pre><code>sudo cherokee-admin
</code></pre><p><strong>注意： cherokee-admin 会显示用户名，一次性密码和web管理界面地址。</strong></p><p><strong>请记录下这个一次性密码，登录到管理界面时需要它。</strong></p><p>默认情况下，只能通过localhost访问Cherokee-admin，如果需要通过其它网络地址来访问，可以使用‘<strong>-b</strong>’参数。如果不指定任何IP地址，Cherokee-admin会自动监听所有网络端口。然后就可以通过网络访问Cherokee-admin</p><pre><code>sudo cherokee-admin -b
</code></pre><p>通过指定IP地址访问Cherokee-admin</p><pre><code>sudo cherokee-admin -b 192.168.1.102
</code></pre><h3 id="_5-浏览cherokee-admin面板" tabindex="-1">5. 浏览cherokee-admin面板 <a class="header-anchor" href="#_5-浏览cherokee-admin面板" aria-label="Permalink to “5. 浏览cherokee-admin面板”">​</a></h3>`,30)),r("p",null,[e[1]||(e[1]=t("在你喜欢的浏览器中输入地址",-1)),e[2]||(e[2]=r("code",null,"http://主机名或 IP 地址:9090/",-1)),e[3]||(e[3]=t("就可以进入控制面板了。例如我的是",-1)),n(o,{href:"http://127.0.0.1:9090/%EF%BC%8C%E5%9C%A8%E6%B5%8F%E8%A7%88%E5%99%A8%E4%B8%AD%E6%98%BE%E7%A4%BA%E5%A6%82%E4%B8%8B%E5%9B%BE"},{default:a(()=>[...e[0]||(e[0]=[t("http://127.0.0.1:9090/，在浏览器中显示如下图",-1)])]),_:1})]),e[18]||(e[18]=r("p",null,[r("img",{src:"http://blog.linoxide.com/wp-content/uploads/2014/12/cherokee-admin.png",alt:"cherokee-admin-panel"})],-1)),e[19]||(e[19]=r("p",null,"好了，到这里我们已经成功地在Ubuntu Server上安装和配置了Cherokee。",-1)),e[20]||(e[20]=r("hr",null,null,-1)),r("p",null,[e[5]||(e[5]=t("via: ",-1)),n(o,{href:"http://linoxide.com/ubuntu-how-to/install-cherokee-lightweight-web-server-ubuntu-14-04/"},{default:a(()=>[...e[4]||(e[4]=[t("http://linoxide.com/ubuntu-how-to/install-cherokee-lightweight-web-server-ubuntu-14-04/",-1)])]),_:1})]),r("p",null,[e[9]||(e[9]=t("作者：",-1)),n(o,{href:"http://linoxide.com/author/arunp/"},{default:a(()=>[...e[6]||(e[6]=[t("Arun Pyasi",-1)])]),_:1}),e[10]||(e[10]=t(" 译者：",-1)),n(o,{href:"https://github.com/ictlyh"},{default:a(()=>[...e[7]||(e[7]=[t("ictlyh",-1)])]),_:1}),e[11]||(e[11]=t(" 校对：",-1)),n(o,{href:"https://github.com/wxy"},{default:a(()=>[...e[8]||(e[8]=[t("wxy",-1)])]),_:1})]),r("p",null,[e[14]||(e[14]=t("本文由 ",-1)),n(o,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...e[12]||(e[12]=[t("LCTT",-1)])]),_:1}),e[15]||(e[15]=t(" 原创翻译，",-1)),n(o,{href:"http://linux.cn/"},{default:a(()=>[...e[13]||(e[13]=[t("Linux中国",-1)])]),_:1}),e[16]||(e[16]=t(" 荣誉推出",-1))])])}const S=p(s,[["render",h]]);export{f as __pageData,S as default};
